function rowCard(k,r){if(k==='creators')return card(r.target,C.roles[r.role]||r.role,r.scope==='whole-text'?'Whole text':r.scope,r,[...(r.creditedAs?[badge('Credited as '+r.creditedAs)]:[])]);if(k==='editions')return card(r,r.language==='en'?'English edition example':'Dutch edition example','Printing and publication history remain incomplete.',r);if(k==='memberships')return card(r.target,currentNode().type==='collection'?'Includes this work':'Collected in','Contents order '+(r.order===null?'not verified':r.order)+(r.editionIds.length?' · edition-specific evidence':''),r);if(k==='publications'){const a=element('article',undefined,'card'),copy=element('div',undefined,'card-link');copy.append(element('h3',C.dateLabel(r.date)),element('p',(r.publisher||'Publisher unconfirmed')+' · '+(r.eventType==='source-reported-release'?'Source-reported publication':r.eventType.replaceAll('-',' '))),element('p','Not automatically a first publication.','muted'));a.append(copy,evidence(r));return a;}const a=card(r.target,currentNode().type==='adaptation'?'Possible literary source':'Possible screen connection',r.status==='provisional'?'Provisional source candidate. This is not an established adaptation relationship.':'Insufficient source evidence. This is not an established adaptation relationship.',{verification:'provisional'}),d=element('details',undefined,'evidence');d.append(element('summary','Candidate sources'));for(const url of r.sourceUrls){const l=element('a',new URL(url).hostname);l.href=url;l.target='_blank';l.rel='noopener';d.append(l,element('p','Reviewed '+r.checked));}a.append(d);return a;}
